CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, email text UNIQUE NOT NULL, password_hash text, verified boolean NOT NULL DEFAULT false, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS companies (id uuid PRIMARY KEY, name text NOT NULL, logo text DEFAULT '', contact text DEFAULT '', currency text NOT NULL DEFAULT 'INR', timezone text NOT NULL DEFAULT 'Asia/Kolkata', fy_start integer NOT NULL DEFAULT 4 CHECK(fy_start BETWEEN 1 AND 12), next_client integer NOT NULL DEFAULT 1, defaults jsonb NOT NULL DEFAULT '{}', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS members (company_id uuid NOT NULL REFERENCES companies(id), user_id uuid NOT NULL REFERENCES users(id), role text NOT NULL CHECK(role IN ('Owner','Manager','Accountant','Staff')), PRIMARY KEY(company_id,user_id));
CREATE TABLE IF NOT EXISTS sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS auth_tokens (token_hash text PRIMARY KEY, user_id uuid REFERENCES users(id), company_id uuid REFERENCES companies(id), email text NOT NULL, kind text NOT NULL, role text, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS mail_outbox (id uuid PRIMARY KEY, email text NOT NULL, subject text NOT NULL, body text NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS clients (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id), reference text NOT NULL, bride text NOT NULL DEFAULT '', groom text NOT NULL DEFAULT '', contact text DEFAULT '', phone text DEFAULT '', alternate_phone text DEFAULT '', email text DEFAULT '', address text DEFAULT '', lead_source text DEFAULT '', booking_date date, status text NOT NULL DEFAULT 'Confirmed', package_description text DEFAULT '', package_amount bigint NOT NULL DEFAULT 0 CHECK(package_amount>=0), addons bigint NOT NULL DEFAULT 0 CHECK(addons>=0), discount bigint NOT NULL DEFAULT 0 CHECK(discount>=0), cancellation_value bigint NOT NULL DEFAULT 0 CHECK(cancellation_value>=0), balance_due_date date, notes text DEFAULT '', archived boolean NOT NULL DEFAULT false, created_at timestamptz DEFAULT now(), UNIQUE(company_id,reference), UNIQUE(company_id,id));
CREATE TABLE IF NOT EXISTS crew (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id), name text NOT NULL, category text DEFAULT 'Photographer', phone text DEFAULT '', payment_details text DEFAULT '', city text DEFAULT '', notes text DEFAULT '', archived boolean DEFAULT false, UNIQUE(company_id,id), UNIQUE(company_id,name));
CREATE TABLE IF NOT EXISTS vendors (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id), name text NOT NULL, type text DEFAULT 'Other', phone text DEFAULT '', email text DEFAULT '', payment_details text DEFAULT '', address text DEFAULT '', notes text DEFAULT '', archived boolean DEFAULT false, UNIQUE(company_id,id), UNIQUE(company_id,name));
CREATE TABLE IF NOT EXISTS events (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id), client_id uuid NOT NULL, event_type text NOT NULL, date date NOT NULL, start_time time, end_time time, venue text DEFAULT '', status text DEFAULT 'Assigned', notes text DEFAULT '', UNIQUE(company_id,id), FOREIGN KEY(company_id,client_id) REFERENCES clients(company_id,id));
CREATE TABLE IF NOT EXISTS rates (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id), crew_id uuid NOT NULL, role text NOT NULL, event_type text NOT NULL DEFAULT 'All functions', amount bigint NOT NULL CHECK(amount>=0), notes text DEFAULT '', FOREIGN KEY(company_id,crew_id) REFERENCES crew(company_id,id), UNIQUE(company_id,crew_id,role,event_type), UNIQUE(company_id,id));
CREATE TABLE IF NOT EXISTS assignments (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id), event_id uuid NOT NULL, crew_id uuid NOT NULL, role text NOT NULL, amount bigint CHECK(amount>=0), override_reason text DEFAULT '', FOREIGN KEY(company_id,event_id) REFERENCES events(company_id,id), FOREIGN KEY(company_id,crew_id) REFERENCES crew(company_id,id), UNIQUE(company_id,event_id,crew_id,role), UNIQUE(company_id,id));
CREATE TABLE IF NOT EXISTS client_payments (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id), client_id uuid NOT NULL, date date NOT NULL, type text NOT NULL DEFAULT 'Advance', amount bigint NOT NULL CHECK(amount>0), mode text DEFAULT 'Bank Transfer', reference text DEFAULT '', notes text DEFAULT '', FOREIGN KEY(company_id,client_id) REFERENCES clients(company_id,id), UNIQUE(company_id,id));
CREATE TABLE IF NOT EXISTS crew_payments (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id), client_id uuid NOT NULL, crew_id uuid NOT NULL, date date NOT NULL, type text DEFAULT 'Advance', amount bigint NOT NULL CHECK(amount>0), mode text DEFAULT 'Bank Transfer', reference text DEFAULT '', notes text DEFAULT '', FOREIGN KEY(company_id,client_id) REFERENCES clients(company_id,id), FOREIGN KEY(company_id,crew_id) REFERENCES crew(company_id,id), UNIQUE(company_id,id));
CREATE TABLE IF NOT EXISTS jobs (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id), client_id uuid NOT NULL, vendor_id uuid NOT NULL, work_type text NOT NULL, description text DEFAULT '', quantity integer NOT NULL DEFAULT 1 CHECK(quantity>0), amount bigint NOT NULL DEFAULT 0 CHECK(amount>=0), date_sent date, due_date date, date_received date, status text DEFAULT 'Not Started', notes text DEFAULT '', FOREIGN KEY(company_id,client_id) REFERENCES clients(company_id,id), FOREIGN KEY(company_id,vendor_id) REFERENCES vendors(company_id,id), UNIQUE(company_id,id));
CREATE TABLE IF NOT EXISTS vendor_payments (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id), job_id uuid NOT NULL, date date, type text DEFAULT 'Advance', amount bigint NOT NULL CHECK(amount>0), mode text DEFAULT '', reference text DEFAULT '', notes text DEFAULT '', FOREIGN KEY(company_id,job_id) REFERENCES jobs(company_id,id), UNIQUE(company_id,id));
CREATE TABLE IF NOT EXISTS expenses (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id), client_id uuid, date date NOT NULL, category text NOT NULL, description text DEFAULT '', amount bigint NOT NULL CHECK(amount>0), paid_by text DEFAULT '', mode text DEFAULT '', reference text DEFAULT '', FOREIGN KEY(company_id,client_id) REFERENCES clients(company_id,id), UNIQUE(company_id,id));
CREATE TABLE IF NOT EXISTS deliverables (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id), client_id uuid NOT NULL, type text NOT NULL, specifications text DEFAULT '', quantity integer NOT NULL DEFAULT 1 CHECK(quantity>0), promised_date date, delivered_date date, status text DEFAULT 'Not Started', notes text DEFAULT '', FOREIGN KEY(company_id,client_id) REFERENCES clients(company_id,id), UNIQUE(company_id,id));
CREATE TABLE IF NOT EXISTS albums (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id), client_id uuid NOT NULL, name text NOT NULL, style text DEFAULT '', size text DEFAULT '', pages integer CHECK(pages>=0), material text DEFAULT '', copies integer NOT NULL DEFAULT 1 CHECK(copies>0), designer_id uuid, printer_id uuid, designer_job_id uuid, printer_job_id uuid, selection_sent date, design_approved date, print_sent date, delivered_date date, status text DEFAULT 'Selection Pending', notes text DEFAULT '', FOREIGN KEY(company_id,client_id) REFERENCES clients(company_id,id), FOREIGN KEY(company_id,designer_id) REFERENCES vendors(company_id,id), FOREIGN KEY(company_id,printer_id) REFERENCES vendors(company_id,id), FOREIGN KEY(company_id,designer_job_id) REFERENCES jobs(company_id,id), FOREIGN KEY(company_id,printer_job_id) REFERENCES jobs(company_id,id), UNIQUE(company_id,id));
CREATE TABLE IF NOT EXISTS audit_log (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id), user_id uuid REFERENCES users(id), entity text NOT NULL, record_id uuid, action text NOT NULL, before_value jsonb, after_value jsonb, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS imports (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id), file_hash text NOT NULL, summary jsonb NOT NULL, created_at timestamptz DEFAULT now(), UNIQUE(company_id,file_hash));
CREATE TABLE IF NOT EXISTS import_previews (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id), user_id uuid NOT NULL REFERENCES users(id), file_hash text NOT NULL, payload jsonb NOT NULL, expires_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS events_company_date ON events(company_id,date);
CREATE INDEX IF NOT EXISTS clients_company_status ON clients(company_id,status);
CREATE INDEX IF NOT EXISTS payments_company_date ON client_payments(company_id,date);
CREATE INDEX IF NOT EXISTS jobs_company_due ON jobs(company_id,due_date);
CREATE INDEX IF NOT EXISTS deliverables_company_due ON deliverables(company_id,promised_date);
CREATE INDEX IF NOT EXISTS audit_company_time ON audit_log(company_id,created_at);

CREATE INDEX IF NOT EXISTS crew_company_idx ON crew(company_id);
CREATE INDEX IF NOT EXISTS vendors_company_idx ON vendors(company_id);
CREATE INDEX IF NOT EXISTS rates_company_idx ON rates(company_id);
CREATE INDEX IF NOT EXISTS assignments_company_idx ON assignments(company_id);
CREATE INDEX IF NOT EXISTS crew_payments_company_idx ON crew_payments(company_id);
CREATE INDEX IF NOT EXISTS vendor_payments_company_idx ON vendor_payments(company_id);
CREATE INDEX IF NOT EXISTS expenses_company_idx ON expenses(company_id);
CREATE INDEX IF NOT EXISTS albums_company_idx ON albums(company_id);
CREATE INDEX IF NOT EXISTS imports_company_idx ON imports(company_id);
CREATE UNIQUE INDEX IF NOT EXISTS crew_company_name_ci ON crew(company_id,lower(name));
CREATE UNIQUE INDEX IF NOT EXISTS vendors_company_name_ci ON vendors(company_id,lower(name));
